"""Req2Test-native editorial administration console."""

from __future__ import annotations

import json


def render_admin_forbidden_html() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>Req2Test · Forbidden</title><style>body{margin:0;background:#f3f4f2;color:#12171f;font-family:Inter,-apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,sans-serif}main{width:min(calc(100% - 64px),1100px);margin:18vh auto}h1{font-size:clamp(64px,8vw,110px);line-height:.84;letter-spacing:-.06em;font-weight:500}p{color:#68717d;font-size:16px}a{display:inline-block;margin-top:30px;padding:14px 18px;background:#0f1823;color:white;text-decoration:none;font-size:12px}</style></head><body><main><div>403 / ACCESS CONTROL</div><h1>ADMIN<br>ONLY.</h1><p>当前账户没有管理控制台权限。</p><a href="/workbench">RETURN TO WORKBENCH →</a></main></body></html>"""


def render_admin_html(view: str) -> str:
    view_json = json.dumps(view)
    return r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Req2Test · Admin Control</title><style>
:root{--paper:#f3f4f2;--blue-paper:#eef2f5;--ink:#12171f;--muted:#68717d;--blue:#5f7fa8;--line:rgba(18,23,31,.11);--dark:#0f1823;--success:#307a5a;--danger:#a84f52;--display:Inter,-apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,sans-serif;--zh:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px var(--display);-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,input,select{font:inherit}.nav{position:sticky;top:18px;z-index:20;width:min(calc(100% - 36px),1400px);height:58px;margin:18px auto 0;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 18px;border:1px solid rgba(255,255,255,.74);border-radius:16px;background:rgba(241,245,247,.82);box-shadow:0 14px 40px rgba(27,39,54,.08);backdrop-filter:blur(18px)}.brand{font-size:14px;font-weight:850;letter-spacing:.12em}.brand b{color:var(--blue)}.links{display:flex;gap:22px}.links a{font-size:11px;font-weight:750;letter-spacing:.065em;white-space:nowrap}.links span{font-family:var(--zh);font-size:10px;color:var(--muted)}.account{justify-self:end;display:flex;gap:14px;align-items:center;font-size:11px}.account button{border:0;background:none;font-weight:750}main{width:min(calc(100% - 64px),1400px);margin:auto;padding:90px 0 120px}.hero{display:grid;grid-template-columns:1.2fr .8fr;align-items:end;gap:60px;padding-bottom:40px;border-bottom:1px solid rgba(18,23,31,.2)}.kicker,.label{font-size:10px;font-weight:800;letter-spacing:.17em;color:var(--muted)}h1{margin:18px 0 0;font-size:clamp(60px,7vw,100px);font-weight:500;line-height:.83;letter-spacing:-.06em}.hero p{justify-self:end;max-width:430px;margin:0;color:var(--muted);font:16px/1.75 var(--zh)}.tabs{display:flex;gap:30px;margin:30px 0 58px;border-bottom:1px solid var(--line)}.tabs a{position:relative;padding:0 0 13px;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.08em}.tabs a.active{color:var(--ink)}.tabs a.active:after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:var(--ink)}.tabs span{font:10px var(--zh)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid rgba(18,23,31,.2);margin-bottom:60px}.metric{min-height:155px;padding:24px 28px 0 0;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.metric:nth-child(3n){border-right:0}.metric:not(:nth-child(3n+1)){padding-left:28px}.metric strong{display:block;font-size:42px;font-weight:500;letter-spacing:-.04em}.metric span{display:block;margin-top:45px;color:var(--muted);font-size:9px;letter-spacing:.11em}.section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}.section-head h2{margin:8px 0 0;font-size:26px;letter-spacing:-.035em}.section-head a{padding:10px 0;border-bottom:1px solid var(--ink);font-size:10px;font-weight:800}.data-list{border-top:1px solid rgba(18,23,31,.2)}.row{display:grid;grid-template-columns:minmax(250px,1.5fr) repeat(4,minmax(90px,.55fr)) auto;gap:22px;align-items:center;padding:21px 0;border-bottom:1px solid var(--line)}.row-title{font-size:18px;font-weight:600}.meta{margin-top:7px;color:var(--muted);font-size:9px;letter-spacing:.05em}.state{font-size:10px;font-weight:850;letter-spacing:.09em}.state.completed,.state.active,.state.healthy,.state.indexed{color:var(--success)}.state.failed,.state.inactive,.state.unavailable{color:var(--danger)}.actions{display:flex;gap:8px}.actions button,.filter button{padding:8px 10px;border:1px solid var(--line);background:transparent;font-size:9px;font-weight:800}.actions button:hover{border-color:var(--ink)}.filter{display:grid;grid-template-columns:1fr 180px auto;gap:10px;margin-bottom:18px}.filter input,.filter select{padding:12px;border:1px solid var(--line);background:rgba(255,255,255,.4)}.filter button{background:var(--dark);color:white;padding-inline:17px}.service-grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid rgba(18,23,31,.2)}.service{min-height:170px;padding:25px 28px 20px 0;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.service:nth-child(3n){border-right:0}.service:not(:nth-child(3n+1)){padding-left:28px}.service h3{margin:0;font-size:19px}.service .state{display:block;margin-top:58px}.knowledge-callout{display:grid;grid-template-columns:1.2fr .8fr;gap:45px;padding:45px;background:var(--blue-paper)}.knowledge-callout h2{margin:0;font-size:44px;line-height:.95;letter-spacing:-.045em}.knowledge-callout div:last-child{align-self:end;color:var(--muted);line-height:1.7}.dark-link{display:inline-block;margin-top:20px;padding:13px 16px;background:var(--dark);color:#fff;font-size:10px;font-weight:800}.empty{padding:50px 0;color:var(--muted)}@media(max-width:1000px){.links{display:none}.metrics,.service-grid{grid-template-columns:repeat(2,1fr)}.metric:nth-child(n),.service:nth-child(n){padding-left:18px;padding-right:18px;border-right:1px solid var(--line)}.metric:nth-child(2n),.service:nth-child(2n){border-right:0}.row{grid-template-columns:1fr 100px auto}.row>*:nth-child(3),.row>*:nth-child(4),.row>*:nth-child(5){display:none}}@media(max-width:720px){main{width:calc(100% - 36px);padding-top:60px}.hero,.knowledge-callout{grid-template-columns:1fr}.hero p{justify-self:start}.tabs{overflow:auto}.metrics,.service-grid{grid-template-columns:1fr}.metric:nth-child(n),.service:nth-child(n){border-right:0}.filter{grid-template-columns:1fr}.row{grid-template-columns:1fr}.row>*:not(:first-child):not(.actions){display:none}}
</style></head><body><header class="nav"><a class="brand" href="/workbench">REQ<b>2</b>TEST</a><nav class="links"><a href="/workbench">WORKBENCH <span>/ 工作台</span></a><a href="/tasks">TASKS <span>/ 测试任务</span></a><a href="/knowledge">KNOWLEDGE <span>/ 知识库</span></a><a href="/workflow">HOW IT WORKS <span>/ 工作流程</span></a><a href="/system">SYSTEM <span>/ 系统状态</span></a></nav><div class="account"><span id="account"></span><button onclick="logout()">LOG OUT / 退出</button></div></header><main><section class="hero"><div><div class="kicker">REQ2TEST / ADMINISTRATION</div><h1>ADMIN<br>CONTROL.</h1></div><p>真实用户、测试任务、知识资产与基础设施状态的统一管理视图。</p></section><nav class="tabs"><a data-view="overview" href="/admin">OVERVIEW <span>/ 总览</span></a><a data-view="users" href="/admin/users">USERS <span>/ 用户</span></a><a data-view="tasks" href="/admin/tasks">TASKS <span>/ 任务</span></a><a data-view="knowledge" href="/admin/knowledge">KNOWLEDGE <span>/ 知识库</span></a><a data-view="system" href="/admin/system">SYSTEM <span>/ 系统</span></a></nav><div id="content"><div class="empty">LOADING / 正在加载</div></div></main><script>
const VIEW=__VIEW__;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pct=v=>v==null?'—':Math.round(Number(v)*100)+'%';const fmt=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';async function af(url,o){const r=await fetch(url,o);if(r.status===401){location.replace('/login?next='+encodeURIComponent(location.pathname));throw Error('AUTH')}return r}async function logout(){await fetch('/api/v1/auth/logout',{method:'POST'});location.replace('/login')}function taskRow(x){return `<a class="row" href="/tasks/${x.id}"><div><div class="row-title">${esc(x.title)}</div><div class="meta">${esc(x.id)} · ${esc(x.user_email||'UNASSIGNED')}</div></div><div class="state ${esc(x.status)}">${esc(x.status).toUpperCase()}</div><div>${fmt(x.created_at)}</div><div>${x.summary?.total_test_cases??0} CASES</div><div>${pct(x.summary?.http_pass_rate)} HTTP</div><div>→</div></a>`}async function overview(){const r=await af('/api/v1/admin/dashboard'),d=await r.json(),m=d.metrics;content.innerHTML=`<div class="metrics">${[['total_users','TOTAL USERS'],['active_users','ACTIVE USERS'],['total_tasks','TOTAL TASKS'],['completed_tasks','COMPLETED TASKS'],['failed_tasks','FAILED TASKS'],['http_pass_rate','HTTP PASS RATE']].map(([k,l])=>`<div class="metric"><strong>${k==='http_pass_rate'?pct(m[k]):m[k]}</strong><span>${l}</span></div>`).join('')}</div><div class="section-head"><div><div class="label">01 / ACTIVITY</div><h2>RECENT TASKS / 最近任务</h2></div><a href="/admin/tasks">VIEW ALL →</a></div><div class="data-list">${d.recent_tasks.map(taskRow).join('')||'<div class="empty">NO TASKS</div>'}</div>`}async function usersView(){const r=await af('/api/v1/admin/users'),d=await r.json();content.innerHTML=`<div class="section-head"><div><div class="label">01 / ACCOUNTS</div><h2>USER MANAGEMENT / 用户管理</h2></div><span>${d.total} USERS</span></div><div class="data-list">${d.items.map(u=>`<div class="row"><div><div class="row-title">${esc(u.email)}</div><div class="meta">${esc(u.id)}</div></div><div class="state ${u.is_active?'active':'inactive'}">${u.is_active?'ACTIVE':'INACTIVE'}</div><div>${esc(u.role).toUpperCase()}</div><div>${fmt(u.created_at)}</div><div></div><div class="actions"><button onclick="statusChange('${u.id}',${!u.is_active})">${u.is_active?'DISABLE':'ENABLE'}</button><button onclick="roleChange('${u.id}','${u.role==='admin'?'user':'admin'}')">${u.role==='admin'?'DEMOTE':'PROMOTE'}</button></div></div>`).join('')}</div>`}async function statusChange(id,value){const r=await af(`/api/v1/admin/users/${id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({is_active:value})});if(!r.ok)alert((await r.json()).detail);await usersView()}async function roleChange(id,role){const r=await af(`/api/v1/admin/users/${id}/role`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({role})});if(!r.ok)alert((await r.json()).detail);await usersView()}async function tasksView(){content.innerHTML=`<form class="filter" onsubmit="loadAdminTasks(event)"><input id="keyword" placeholder="SEARCH TITLE OR REQUIREMENT"><select id="taskStatus"><option value="">ALL STATUS</option><option>completed</option><option>failed</option><option>running</option><option>queued</option></select><button>FILTER →</button></form><div id="adminTaskList"></div>`;await loadAdminTasks()}async function loadAdminTasks(e){e?.preventDefault();const q=new URLSearchParams(),k=document.getElementById('keyword')?.value,s=document.getElementById('taskStatus')?.value;if(k)q.set('keyword',k);if(s)q.set('status',s);const r=await af('/api/v1/admin/tasks?'+q),d=await r.json();adminTaskList.innerHTML=`<div class="data-list">${d.items.map(taskRow).join('')||'<div class="empty">NO TASKS</div>'}</div>`}async function knowledgeView(){const r=await af('/api/v1/knowledge/documents'),d=await r.json();content.innerHTML=`<div class="knowledge-callout"><div><div class="label">PLATFORM RAG</div><h2>${d.total} KNOWLEDGE<br>DOCUMENTS.</h2></div><div>知识库索引、检索预览、上传、重新索引与删除统一复用产品级 Knowledge 页面。<br><a class="dark-link" href="/knowledge">OPEN KNOWLEDGE CONTROL →</a></div></div>`}async function systemView(){const r=await af('/api/v1/admin/system'),d=await r.json();content.innerHTML=`<div class="section-head"><div><div class="label">01 / INFRASTRUCTURE</div><h2>RUNTIME STATUS / 运行状态</h2></div></div><div class="service-grid">${d.services.map(x=>`<article class="service"><h3>${esc(x.name)}</h3><span class="state ${String(x.state).toLowerCase()}">${esc(x.state)}</span><div class="meta">${esc(x.basis)}${x.documents==null?'':' · '+x.documents+' DOCUMENTS'}</div></article>`).join('')}</div>`}async function boot(){const r=await af('/api/v1/auth/me'),me=await r.json();account.textContent=me.email;document.querySelector(`[data-view="${VIEW}"]`).classList.add('active');({overview,users:usersView,tasks:tasksView,knowledge:knowledgeView,system:systemView}[VIEW])()}boot();
</script></body></html>""".replace("__VIEW__", view_json)
